#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Audios;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.rain)]
    public class Rain : EffectBehaviour
    {
        public Rain(string nsp, string name) : base(nsp, name)
        {
            AddAura(new RainingAura());
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.GetAuraEffect<RainingAura>()?.UpdateAura();
            entity.Level.AddLoopSoundEntity(VanillaSoundID.rain, entity.ID);
        }
        public class RainingAura : AuraEffectDefinition
        {
            public RainingAura() : base(VanillaBuffID.Level.raining, 0)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                results.Add(auraEffect.Level);
            }
        }
    }
}